request:
{
 "project": "OUTBREAK MANAGEMENT FUNCTIONAL REQUIREMENTS",
 "meeting": "1 of 1 (kickoff)",
 "participants": [
  "Analyst",
  "Client",
  "EndUser",
  "TechLead"
 ],
 "previous_turns_for_context_only": [
  {
   "speaker": "Client",
   "act": "state",
   "content": [
    "Epidemiological (epi) data must be collected to assist in the case investigation of events."
   ]
  },
  {
   "speaker": "Analyst",
   "act": "backchannel"
  },
  {
   "speaker": "Client",
   "act": "state",
   "content": [
    "Detailed data must be collected about the source of exposure as well as the exposed entity to support contact exposure tracing.",
    "Epi data must be collected to assist in the exposure investigation of health events."
   ]
  }
 ],
 "turns": [
  {
   "id": "M1:T41",
   "speaker": "Analyst",
   "act": "backchannel",
   "guide": "Short acknowledgment while listening (1-3 words)."
  },
  {
   "id": "M1:T42",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'specimen/sample collection and laboratory response data' and asks about it."
  },
  {
   "id": "M1:T43",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Specimen/sample collection and laboratory response data supports the collection of clinical specimens, food samples, environmental samples, and other types of samples that will be tested for biological, chemical, and radiological agents.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T44",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Specimens/samples collected for laboratory testing must be assigned an identifier (i.e., Specimen ID) that is unique within the jurisdiction.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T45",
   "speaker": "EndUser",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Systems supporting OM must be able to store data about the specimens/samples that are collected for laboratory testing.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T46",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Environmental sample data should include information about the collection method, location (geocoded if possible) from which the sample was taken, source (e.g., rain or well for water, radiation release, asbestos, chair or desk in a specified location), nature of the sample (e.g., soil, water, air), quality control data, collection begin and end date and time for air samples, and original volume and volume of concentrate tested for water samples.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T47",
   "speaker": "Analyst",
   "act": "echo",
   "guide": "Analyst paraphrases the content back as a question, to confirm understanding.",
   "content": [
    {
     "text": "Environmental sample data should include information about the collection method, location (geocoded if possible) from which the sample was taken, source (e.g., rain or well for water, radiation release, asbestos, chair or desk in a specified location), nature of the sample (e.g., soil, water, air), quality control data, collection begin and end date and time for air samples, and original volume and volume of concentrate tested for water samples.",
     "role": "echo"
    }
   ]
  },
  {
   "id": "M1:T48",
   "speaker": "Client",
   "act": "confirm",
   "guide": "Short confirmation that the paraphrase is right."
  },
  {
   "id": "M1:T49",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Food sample data should include information about the lot number, batch number, manufacturer name, shipping invoice, temperature, sample type (e.g., dairy – milk, red meat, spice), and product storage condition.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T50",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Systems supporting OM must be able to create a laboratory test request for a specimen/sample or group of specimens/samples.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T51",
   "speaker": "Analyst",
   "act": "backchannel",
   "guide": "Short acknowledgment while listening (1-3 words)."
  },
  {
   "id": "M1:T52",
   "speaker": "EndUser",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "All levels of granularity of results (e.g., specimen/sample level, assay level) must be supported.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T53",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'prophylaxis and treatment data' and asks about it."
  },
  {
   "id": "M1:T54",
   "speaker": "EndUser",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Systems supporting OM should capture or be linked to data regarding the prophylaxis or treatment to cases, exposed individuals, or at risk persons, including the person who ordered the prophylaxis or treatment, and the name, date, type, duration, and dosage of the treatment or prophylaxis given.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T55",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'activity logging data' and asks about it."
  },
  {
   "id": "M1:T56",
   "speaker": "EndUser",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Systems supporting OM should capture information such as the date and time of an activity, activity type, who initiated the activity, and contact information to generate activity logs for management purposes.",
     "role": "statement"
    },
    {
     "text": "Activity logs, which are tools for investigators to track their actions during a case, should be supported.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T57",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "For example, if a person becomes ill during travel in one jurisdiction but is the resident of another, the illness will be reported by the state (jurisdiction) of residence, rather than by the jurisdiction visited.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T58",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'case investigation' and asks about it."
  },
  {
   "id": "M1:T59",
   "speaker": "EndUser",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Electronic questionnaires must be developed and validated.",
     "role": "statement"
    },
    {
     "text": "Systems supporting OM must provide the ability to control the configuration of and revisions to investigation-specific questionnaires.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T60",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Systems supporting OM must provide the ability to publish investigation-specific questionnaires and implementation guides.",
     "role": "statement"
    }
   ]
  }
 ]
}
